function validate([buildings]) {
  const MAX = 2147483647;
  if (buildings.length < 1 || buildings.length > 10000) return 'buildings needs 1 to 10^4 entries.';
  for (let i = 0; i < buildings.length; i++) {
    const b = buildings[i];
    if (!Array.isArray(b) || b.length !== 3 || !b.every(Number.isInteger)) return 'Each building is [left, right, height] with whole numbers.';
    const [left, right, height] = b;
    if (left < 0 || left >= right || right > MAX) return 'Each building needs 0 <= left < right <= 2^31 - 1.';
    if (height < 1 || height > MAX) return 'Each height is between 1 and 2^31 - 1.';
    if (i > 0 && left < buildings[i - 1][0]) return 'buildings must be sorted by left edge.';
  }
  return null;
}

