function getSkyline(buildings) {
  // Max-heap of [height, right] pairs, ordered by height.
  const heap = [];
  const higher = (a, b) => heap[a][0] > heap[b][0];
  const swap = (a, b) => {
    [heap[a], heap[b]] = [heap[b], heap[a]];
  };
  const push = (item) => {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0 && higher(child, (child - 1) >> 1)) {
      swap(child, (child - 1) >> 1);
      child = (child - 1) >> 1;
    }
  };
  const pop = () => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const first = 2 * parent + 1;
      let top = parent;
      if (first < heap.length && higher(first, top)) top = first;
      if (first + 1 < heap.length && higher(first + 1, top)) top = first + 1;
      if (top === parent) return;
      swap(top, parent);
      parent = top;
    }
  };

  const xs = [...new Set(buildings.flatMap(([left, right]) => [left, right]))].sort((a, b) => a - b);
  const skyline = [];
  let next = 0;

  for (const x of xs) {
    while (next < buildings.length && buildings[next][0] <= x) {
      push([buildings[next][2], buildings[next][1]]);
      next++;
    }
    while (heap.length > 0 && heap[0][1] <= x) {
      pop();
    }
    const height = heap.length > 0 ? heap[0][0] : 0;
    if (skyline.length === 0 || skyline[skyline.length - 1][1] !== height) {
      skyline.push([x, height]);
    }
  }
  return skyline;
}

