function getSkyline(buildings) {
  // The outline can only change at an edge; measure the height at every edge directly.
  const edges = [];
  for (const [left, right] of buildings) edges.push(left, right);
  edges.sort((a, b) => a - b);
  const result = [];
  for (let k = 0; k < edges.length; k++) {
    if (k > 0 && edges[k] === edges[k - 1]) continue;
    const x = edges[k];
    let tallest = 0;
    for (const [left, right, height] of buildings) if (left <= x && x < right) tallest = Math.max(tallest, height);
    if (!result.length || result[result.length - 1][1] !== tallest) result.push([x, tallest]);
  }
  return result;
}

