function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const MAX = 2147483647;
  const buildings = [];
  if (size === 'large') {
    const n = int(1500, 2000);
    const wide = rand() < 0.3;
    for (let i = 0; i < n; i++) {
      if (wide) {
        const left = int(0, MAX - 1);
        buildings.push([left, int(left + 1, MAX), int(1, MAX)]);
      } else {
        const left = int(0, 20000);
        buildings.push([left, left + int(1, 500), int(1, rand() < 0.5 ? 50 : 1000000)]);
      }
    }
  } else {
    const n = int(1, 6);
    for (let i = 0; i < n; i++) {
      const left = int(0, 12);
      buildings.push([left, left + int(1, 6), int(1, 5)]);
    }
  }
  buildings.sort((a, b) => a[0] - b[0]);
  return [buildings];
}
